    \partsitem Show that this gives 
      the equation of a line in \( \Re^2 \) through
      \( (x_2,y_2) \) and \( (x_3,y_3) \).
      \begin{equation*}
        \begin{vmat}
          x    &x_2 &x_3  \\
          y    &y_2 &y_3  \\
          1    &1   &1
        \end{vmat}=0
      \end{equation*}
